create policy "anyone reads product images" on storage.objects for select to anon, authenticated using (bucket_id = 'product-images');
create policy "staff upload product images" on storage.objects for insert to authenticated with check (bucket_id = 'product-images' and (public.can(auth.uid(),'product:edit') or public.can(auth.uid(),'settings:edit') or public.can(auth.uid(),'offers:edit')));
create policy "staff delete product images" on storage.objects for delete to authenticated using (bucket_id = 'product-images' and public.can(auth.uid(),'product:edit'));